package com.andye.warmod.rocket.client;import com.andye.warmod.entity.RocketProjectileEntity;import com.andye.warmod.warhead.client.render.WarheadRenderPipelines;import com.mojang.blaze3d.vertex.PoseStack;import net.minecraft.client.renderer.SubmitNodeCollector;import net.minecraft.client.renderer.entity.*;import net.minecraft.client.renderer.state.level.CameraRenderState;import org.joml.*;public final class RocketProjectileRenderer extends EntityRenderer<RocketProjectileEntity,RocketProjectileRenderState>{public RocketProjectileRenderer(EntityRendererProvider.Context c){super(c);shadowRadius=0;}@Override public RocketProjectileRenderState createRenderState(){return new RocketProjectileRenderState();}@Override public void extractRenderState(RocketProjectileEntity e,RocketProjectileRenderState s,float partial){super.extractRenderState(e,s,partial);s.velocity=e.getDeltaMovement();s.payloadType=e.payloadType();s.visualSeed=e.visualSeed();s.ageInTicks=e.age()+partial;}@Override public void submit(RocketProjectileRenderState s,PoseStack pose,SubmitNodeCollector collector,CameraRenderState camera){pose.pushPose();Vector3f d=new Vector3f((float)s.velocity.x,(float)s.velocity.y,(float)s.velocity.z);if(d.lengthSquared()>1E-6f){d.normalize();pose.mulPose(new Quaternionf().rotationTo(new Vector3f(0,1,0),d));}collector.submitCustomGeometry(pose,WarheadRenderPipelines.PROJECTILE,(p,b)->RocketProjectileMesh.render(p,b,s));collector.submitCustomGeometry(pose,WarheadRenderPipelines.FIREBALL_HOT,(p,b)->RocketTrailRenderer.renderFlame(p,b,s));collector.submitCustomGeometry(pose,WarheadRenderPipelines.HEAVY_SMOKE,(p,b)->RocketTrailRenderer.renderSmoke(p,b,s));pose.popPose();super.submit(s,pose,collector,camera);}}